import{_ as d,o as a,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"ترتیبات کے تضاد کی خود جانچ کی جدول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/97-设定矛盾自查表.md","filePath":"ur/97-设定矛盾自查表.md","lastUpdated":1789183869000}'),e={name:"ur/97-设定矛盾自查表.md"};function h(l,t,i,u,q,n){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ترتیبات-کے-تضاد-کی-خود-جانچ-کی-جدول" tabindex="-1">ترتیبات کے تضاد کی خود جانچ کی جدول <a class="header-anchor" href="#ترتیبات-کے-تضاد-کی-خود-جانچ-کی-جدول" aria-label="Permalink to &quot;ترتیبات کے تضاد کی خود جانچ کی جدول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>97</td></tr><tr><td>ماڈیول</td><td>ضمیمے اور حوالہ جاتی مواد</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>تضاد کی خود جانچ، ترتیبات کی مطابقت، منطقی تصدیق، معیار کا کنٹرول، ترتیبات کی دیکھ بھال</td></tr></tbody></table><h2 id="_1-تفصیل" tabindex="-1">1. تفصیل <a class="header-anchor" href="#_1-تفصیل" aria-label="Permalink to &quot;1. تفصیل&quot;">​</a></h2><p>ترتیبات کے تضاد کی خود جانچ کی جدول اینکر سمبیوسس تہذیب کے ترتیب کے نظام کا معیار کنٹرول کا آلہ ہے، جو نئی ترتیبات کی تخلیق، پرانی ترتیبات کی ترمیم، اور دستاویز کی تازہ کاری کے دوران ممکنہ ترتیبات کے تضاد اور منطقی عدم مطابقت کو منظم طریقے سے دریافت کرنے کے لیے استعمال ہوتا ہے۔ یہ خود جانچ کی جدول SPEC.md میں قائم کردہ 14 بنیادی ترتیبات اور مطابقت کی جانچ کی فہرست کی بنیاد پر تیار کی گئی ہے، جس میں دنیا کے نقطہ نظر، کھیتی کا نظام، سماجی ادارے، قانونی نظام، زندگی کی شکلیں، ٹیکنالوجی کا نظام، تاریخی ادوار، اور سطحوں کے درمیان تعامل جیسے تمام ماڈیولز کا احاطہ کیا گیا ہے۔ کوئی بھی نئی ترتیب یا ترمیم شدہ مواد کو رسمی طور پر ترتیب کے نظام میں شامل کرنے سے پہلے، اس خود جانچ کی جدول کے تمام جانچ کے آئٹمز کو پاس کرنا ضروری ہے۔</p><h2 id="_2-بنیادی-ترتیبات-کی-مطابقت-کی-جانچ" tabindex="-1">2. بنیادی ترتیبات کی مطابقت کی جانچ <a class="header-anchor" href="#_2-بنیادی-ترتیبات-کی-مطابقت-کی-جانچ" aria-label="Permalink to &quot;2. بنیادی ترتیبات کی مطابقت کی جانچ&quot;">​</a></h2><h3 id="_2-1-کائنات-کا-نام-اور-بنیادی-تصورات" tabindex="-1">2.1 کائنات کا نام اور بنیادی تصورات <a class="header-anchor" href="#_2-1-کائنات-کا-نام-اور-بنیادی-تصورات" aria-label="Permalink to &quot;2.1 کائنات کا نام اور بنیادی تصورات&quot;">​</a></h3><table tabindex="0"><thead><tr><th>جانچ کا آئٹم</th><th>جانچ کا مواد</th><th>پاس کا معیار</th><th>عام مسئلہ</th></tr></thead><tbody><tr><td>C01</td><td>کیا کائنات کا نام یکساں ہے</td><td>پورے متن میں &quot;وان لینگ ہینگ ماؤ بین یوآن ژو&quot; یا مخفف &quot;ہینگ یوآن ژو&quot; یکساں استعمال کریں، دوسرا نام استعمال نہ کریں</td><td>&quot;کائنات&quot;، &quot;دس ہزار جہان&quot;، &quot;آسمان اور جہان&quot; جیسے غیر معیاری ناموں کا اختلاط</td></tr><tr><td>C02</td><td>کیا اینکر کی تعریف مطابقت پذیر ہے</td><td>اینکر ہمیشہ &quot;قانون کے نیٹ ورک میں مستحکم نوڈ&quot; کے طور پر بیان کیا جاتا ہے، اس کی بنیادی خصوصیات کو تبدیل نہ کریں</td><td>اینکر کو چیز، جاندار، یا توانائی کے جسم کے طور پر بیان کرنا</td></tr><tr><td>C03</td><td>کیا سمبیوسس کا تصور یکساں ہے</td><td>سمبیوسس ہمیشہ &quot;مختلف جانداروں کے درمیان باہمی فائدہ مند تعاون کے ذریعے مشترکہ ارتقاء&quot; کا مطلب ہے، لوٹ مار کے خلاف موقف سے انحراف نہ کریں</td><td>سمبیوسس کو انضمام، نگلنا، یا کنٹرول کے طور پر بیان کرنا</td></tr><tr><td>C04</td><td>کیا بنیادی موقف مطابقت پذیر ہے</td><td>ہمیشہ &quot;حقیقت پر مبنی&quot; اصول پر عمل کریں، خیالی ترتیبات کو حقیقت کے طور پر بیان نہ کریں</td><td>خیال اور حقیقت کی حدود کو الجھانا</td></tr></tbody></table><h3 id="_2-2-کھیتی-کے-نظام-کی-مطابقت" tabindex="-1">2.2 کھیتی کے نظام کی مطابقت <a class="header-anchor" href="#_2-2-کھیتی-کے-نظام-کی-مطابقت" aria-label="Permalink to &quot;2.2 کھیتی کے نظام کی مطابقت&quot;">​</a></h3><table tabindex="0"><thead><tr><th>جانچ کا آئٹم</th><th>جانچ کا مواد</th><th>پاس کا معیار</th><th>عام مسئلہ</th></tr></thead><tbody><tr><td>C05</td><td>کیا نظام کی کل تعداد مطابقت پذیر ہے</td><td>اصل کھیتی کے نظام کی کل تعداد ہمیشہ تین سو سیٹ ہے، اضافہ یا کمی نہ کریں</td><td>&quot;تین سو سے زیادہ سیٹ&quot;، &quot;سینکڑوں سیٹ&quot; جیسے مبہم اظہار کی ظاہری شکل</td></tr><tr><td>C06</td><td>کیا نظام کی درجہ بندی مطابقت پذیر ہے</td><td>ہمیشہ چھ زمروں میں تقسیم کریں (اصل تخمینہ، زندگی کا چکر، خلائی قوانین، شعور کی جہت بڑھانا، سمبیوسس نیٹ ورک، اطلاقی انجینئرنگ)، ہر زمرے میں پچاس سیٹ</td><td>دیگر درجہ بندی کے طریقے کی ظاہری شکل یا زمروں کی تعداد میں عدم مطابقت</td></tr><tr><td>C07</td><td>کیا اصل کی تین بنیادیں مطابقت پذیر ہیں</td><td>پہلے تین سیٹ ہمیشہ تخمینہ تکرار (001)، زندگی کا چکر (002)، خلائی قوانین کا انتظام (003)</td><td>پہلے تین سیٹ کے نمبر یا نام تبدیل کرنا</td></tr><tr><td>C08</td><td>کیا بئی زینگ پھل کی ترتیب مطابقت پذیر ہے</td><td>بئی زینگ پھل ہمیشہ &quot;شروعاتی بف&quot; ہے، سو گنا تخمینہ اضافہ فراہم کرتا ہے، پہلے ہی ٹیکنالوجی کے طور پر لاگو کیا جا چکا ہے</td><td>بئی زینگ پھل کو قدرتی پھل یا غیر ٹیکنالوجی کے طور پر بیان کرنا</td></tr><tr><td>C09</td><td>کیا کھیتی کی حدود مطابقت پذیر ہیں</td><td>ہر نظام کی حدود کی تقسیم دستاویز 14 &quot;کھیتی کی حدود کی یکجا تقسیم&quot; کے ساتھ مطابقت پذیر ہے</td><td>یکجا تقسیم سے متصادم حدود کے نام خود ایجاد کرنا</td></tr><tr><td>C10</td><td>کیا لوٹ مار کے خلاف موقف مطابقت پذیر ہے</td><td>لوٹ مار قسم کی کھیتی کو مثبت یا قابل قبول نظام کے طور پر بیان نہ کریں</td><td>لوٹ مار قسم کی کھیتی کی حمایت کرنا یا خوبصورت بیان کرنا</td></tr></tbody></table><h3 id="_2-3-سماجی-اور-قانونی-مطابقت" tabindex="-1">2.3 سماجی اور قانونی مطابقت <a class="header-anchor" href="#_2-3-سماجی-اور-قانونی-مطابقت" aria-label="Permalink to &quot;2.3 سماجی اور قانونی مطابقت&quot;">​</a></h3><table tabindex="0"><thead><tr><th>جانچ کا آئٹم</th><th>جانچ کا مواد</th><th>پاس کا معیار</th><th>عام مسئلہ</th></tr></thead><tbody><tr><td>C11</td><td>کیا تہذیب کی درجہ بندی مطابقت پذیر ہے</td><td>ہمیشہ پانچ قسم کی درجہ بندی (مشرقی ایشیاء کی گھنے، نارڈک فلاح و بہبود، شمالی امریکہ کی کثیر الثقافتی، براعظمی یورپ کی سماجی، ترقی پذیر پیچھا کرنے والی)</td><td>چھٹی قسم کی درجہ بندی کی ظاہری شکل یا درجہ بندی کے نام تبدیل کرنا</td></tr><tr><td>C12</td><td>کیا قانونی نظام مطابقت پذیر ہے</td><td>ہمیشہ آئین + لیبر قانون + صارفین کے تحفظ کا قانون + پانچ تکمیلی قوانین (تعلیم، صحت، رہائش، ماحول، یکجا کاروبار مخالف)</td><td>کسی قانون کو چھوڑنا یا غیر مقررہ قانون شامل کرنا</td></tr><tr><td>C13</td><td>کیا انتظامی ڈھانچہ مطابقت پذیر ہے</td><td>ہمیشہ اینکر کونسل (قانون ساز) + سمبیوسس ایگزیکٹو کمیٹی (انتظامیہ) + سمبیوسس عدالت (عدلیہ) + اینکر نگرانی کمیٹی (نگرانی)</td><td>اداروں کے نام یا اختیارات کی تقسیم تبدیل کرنا</td></tr><tr><td>C14</td><td>کیا مشترکہ پیداوار کے معاہدے کا میکانزم مطابقت پذیر ہے</td><td>ہمیشہ &quot;زیادہ محنت زیادہ فائدہ&quot; پر مرکوز، وسائل کی تقسیم شراکت پر مبنی</td><td>مشترکہ پیداوار کے معاہدے کو مساوات پسندی یا ضرورت کے مطابق تقسیم کے طور پر بیان کرنا</td></tr><tr><td>C15</td><td>کیا 20% ایکٹیویشن کی حکمت عملی مطابقت پذیر ہے</td><td>ہمیشہ ابتدائی مرحلے میں 20% تمام مخلوقات کو سطح کے سب سے طاقتور کے طور پر ایکٹیو کرنا</td><td>ایکٹیویشن کے تناسب یا ہدف تبدیل کرنا</td></tr></tbody></table><h2 id="_3-ماڈیولز-کے-درمیان-منطقی-مطابقت-کی-جانچ" tabindex="-1">3. ماڈیولز کے درمیان منطقی مطابقت کی جانچ <a class="header-anchor" href="#_3-ماڈیولز-کے-درمیان-منطقی-مطابقت-کی-جانچ" aria-label="Permalink to &quot;3. ماڈیولز کے درمیان منطقی مطابقت کی جانچ&quot;">​</a></h2><h3 id="_3-1-ٹائم-لائن-کی-مطابقت" tabindex="-1">3.1 ٹائم لائن کی مطابقت <a class="header-anchor" href="#_3-1-ٹائم-لائن-کی-مطابقت" aria-label="Permalink to &quot;3.1 ٹائم لائن کی مطابقت&quot;">​</a></h3><table tabindex="0"><thead><tr><th>جانچ کا آئٹم</th><th>جانچ کا مواد</th><th>پاس کا معیار</th><th>عام مسئلہ</th></tr></thead><tbody><tr><td>L01</td><td>کیا تاریخی واقعات کا وقت مطابقت پذیر ہے</td><td>تمام تاریخی واقعات کا وقت دستاویز 93 &quot;کرونیکل کا خلاصہ&quot; اور دستاویزات 70-79 کے ساتھ مطابقت پذیر ہے</td><td>ایک ہی واقعہ کے مختلف دستاویزات میں وقت غیر مطابقت پذیر</td></tr><tr><td>L02</td><td>کیا ادوار کی تقسیم مطابقت پذیر ہے</td><td>ادوار کے نام اور شروع اور اختتام کے وقت دستاویز 70 &quot;ادوار کی تقسیم کی عمومی جدول&quot; کے ساتھ مطابقت پذیر ہیں</td><td>غیر مقررہ دور کی ظاہری شکل یا ادوار کی حدود تبدیل کرنا</td></tr><tr><td>L03</td><td>کیا لوگوں کا دور مطابقت پذیر ہے</td><td>اہم لوگوں کی سرگرمی کا دور دستاویز 95 &quot;اہم لوگ اور تنظیمیں&quot; کے ساتھ مطابقت پذیر ہے</td><td>شخص اس دور میں ظاہر ہوتا ہے جس میں وہ موجود نہیں تھا</td></tr><tr><td>L04</td><td>کیا ٹیکنالوجی کے ظاہر ہونے کا وقت مطابقت پذیر ہے</td><td>ہر ٹیکنالوجی کی ایجاد اور پختگی کا وقت کرونیکل کے ساتھ مطابقت پذیر ہے</td><td>کوئی ٹیکنالوجی اس ایجاد سے پہلے کے دور میں استعمال ہوتی ہے</td></tr></tbody></table><h3 id="_3-2-ٹیکنالوجی-کے-نظام-کی-مطابقت" tabindex="-1">3.2 ٹیکنالوجی کے نظام کی مطابقت <a class="header-anchor" href="#_3-2-ٹیکنالوجی-کے-نظام-کی-مطابقت" aria-label="Permalink to &quot;3.2 ٹیکنالوجی کے نظام کی مطابقت&quot;">​</a></h3><table tabindex="0"><thead><tr><th>جانچ کا آئٹم</th><th>جانچ کا مواد</th><th>پاس کا معیار</th><th>عام مسئلہ</th></tr></thead><tbody><tr><td>T01</td><td>کیا کاپی آئینہ کی ٹیکنالوجی مطابقت پذیر ہے</td><td>کاپی آئینہ ہمیشہ &quot;اصل چیز کو چھوئے بغیر 1:1 کاپی کرنے والا آلہ&quot; ہے، کاپی کا عمل صفر مداخلت کے ساتھ</td><td>کاپی آئینہ کو اصل چیز کو تبدیل کرنے کے قابل یا اصل چیز کو چھونے کی ضرورت کے طور پر بیان کرنا</td></tr><tr><td>T02</td><td>کیا الگ تھلگ جگہ مطابقت پذیر ہے</td><td>الگ تھلگ جگہ ہمیشہ &quot;قانون کی دیوار کے ذریعے باہر سے مکمل طور پر الگ تھلگ آزاد جگہ&quot; ہے</td><td>الگ تھلگ جگہ کو عام کمرے یا ورچوئل جگہ کے طور پر بیان کرنا</td></tr><tr><td>T03</td><td>کیا خلائی قوانین کی کھیتی کی ضرورت مطابقت پذیر ہے</td><td>ہر خلائی ٹیکنالوجی کی کھیتی کی ضرورت دستاویز 13 &quot;خلائی قوانین کے انتظام کے نظام کی تفصیلات&quot; کے ساتھ مطابقت پذیر ہے</td><td>کم کھیتی والا شخص اس ٹیکنالوجی کو استعمال کرتا ہے جس کے لیے زیادہ کھیتی کی ضرورت ہے</td></tr><tr><td>T04</td><td>کیا توانائی کی اکائی مطابقت پذیر ہے</td><td>توانائی کی پیمائش یکساں طور پر &quot;معیاری توانائی کی اکائی&quot; استعمال کرتی ہے، دوسری اکائی استعمال نہ کریں</td><td>&quot;روحانی پتھر&quot;، &quot;کرسٹل سکہ&quot; جیسے غیر معیاری توانائی کی اکائیوں کا اختلاط</td></tr></tbody></table><h3 id="_3-3-سطحوں-اور-وقت-کے-قواعد-کی-مطابقت" tabindex="-1">3.3 سطحوں اور وقت کے قواعد کی مطابقت <a class="header-anchor" href="#_3-3-سطحوں-اور-وقت-کے-قواعد-کی-مطابقت" aria-label="Permalink to &quot;3.3 سطحوں اور وقت کے قواعد کی مطابقت&quot;">​</a></h3><table tabindex="0"><thead><tr><th>جانچ کا آئٹم</th><th>جانچ کا مواد</th><th>پاس کا معیار</th><th>عام مسئلہ</th></tr></thead><tbody><tr><td>K01</td><td>کیا &quot;پہلے مشاہدہ کریں، پھر محدود مداخلت کریں&quot; مطابقت پذیر ہے</td><td>تمام وقت کی بازیافت اور سطحوں کے درمیان آپریشنز کو اس اصول پر عمل کرنا ضروری ہے، مشاہدے کے مرحلے کو نہیں چھوڑا جا سکتا</td><td>بغیر مشاہدے کے براہ راست مداخلت کے آپریشن کی وضاحت</td></tr><tr><td>K02</td><td>کیا &quot;صرف علم کی واپسی&quot; مطابقت پذیر ہے</td><td>آثار قدیمہ کی پیداوار صرف تجریدی علم اور معلومات تک محدود ہے، مادے، توانائی، یا جانداروں کو واپس نہیں بھیجا جا سکتا</td><td>آثار قدیمہ کے نمونے یا نمونے کو اپنی سطح پر واپس لانے کے عمل کی وضاحت</td></tr><tr><td>K03</td><td>کیا سفری اجازت کا نظام مطابقت پذیر ہے</td><td>تمام سطحی سفروں کو متعلقہ سطح کی اجازت حاصل کرنی ضروری ہے، بغیر اجازت سفر نہیں کیا جا سکتا</td><td>بغیر اجازت اپنی مرضی سے سفر کی وضاحت</td></tr><tr><td>K04</td><td>کیا وقت کے تضاد کی درجہ بندی مطابقت پذیر ہے</td><td>تضاد ہمیشہ چار زمروں میں تقسیم ہوتا ہے: دادا، معلومات، ہستی، واقعہ، اضافہ یا تبدیلی نہیں کی جا سکتی</td><td>غیر مقررہ تضاد کی قسم کی ظاہری شکل</td></tr><tr><td>K05</td><td>کیا سطح کی درجہ بندی مطابقت پذیر ہے</td><td>سطح ہمیشہ پانچ زمروں میں تقسیم ہوتی ہے (مادی اصل، توانائی کا اظہار، شعور کا غلبہ، قوانین ٹوٹے ہوئے، اصل سے قریبی)</td><td>دیگر درجہ بندی کے طریقے کی ظاہری شکل</td></tr></tbody></table><h3 id="_3-4-زندگی-اور-نسلوں-کی-مطابقت" tabindex="-1">3.4 زندگی اور نسلوں کی مطابقت <a class="header-anchor" href="#_3-4-زندگی-اور-نسلوں-کی-مطابقت" aria-label="Permalink to &quot;3.4 زندگی اور نسلوں کی مطابقت&quot;">​</a></h3><table tabindex="0"><thead><tr><th>جانچ کا آئٹم</th><th>جانچ کا مواد</th><th>پاس کا معیار</th><th>عام مسئلہ</th></tr></thead><tbody><tr><td>S01</td><td>کیا نسلوں کی درجہ بندی مطابقت پذیر ہے</td><td>نسلیں ہمیشہ آٹھ زمروں میں تقسیم ہوتی ہیں (انسانی شکل، جانوروں کی شکل، پودوں کی شکل، عنصری شکل، توانائی کی شکل، شعور کی شکل، مکینیکل شکل، مخلوط شکل)</td><td>دیگر درجہ بندی کے طریقے کی ظاہری شکل</td></tr><tr><td>S02</td><td>کیا عجیب زندگی کا انتظام مطابقت پذیر ہے</td><td>عجیب زندگی ہمیشہ تین قسم کے معیاری انتظام کے طریقہ کار کے مطابق ہوتی ہے</td><td>بغیر طریقہ کار کے اپنی مرضی سے انتظام کی وضاحت</td></tr><tr><td>S03</td><td>کیا تاریکی کے متبادل جسم کا انتظام مطابقت پذیر ہے</td><td>تاریکی کے متبادل جسم ہمیشہ دوہری روح کی اخلاقیات اور چار شاخوں کے انتظام کے قواعد کے مطابق ہوتا ہے</td><td>ایک طرف کی روح کو آسانی سے ختم کرنے کے عمل کی وضاحت</td></tr><tr><td>S04</td><td>کیا تمام نسلوں کی برابری مطابقت پذیر ہے</td><td>تمام ذہین نسلیں قانون کے سامنے برابر ہیں، نسلی امتیاز کی ترتیب نہیں ہو سکتی</td><td>کسی نسل کو فطری طور پر کمتر یا غلامی کے لائق کے طور پر بیان کرنا</td></tr></tbody></table><h2 id="_4-دستاویز-کی-شکل-اور-قواعد-کی-جانچ" tabindex="-1">4. دستاویز کی شکل اور قواعد کی جانچ <a class="header-anchor" href="#_4-دستاویز-کی-شکل-اور-قواعد-کی-جانچ" aria-label="Permalink to &quot;4. دستاویز کی شکل اور قواعد کی جانچ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>جانچ کا آئٹم</th><th>جانچ کا مواد</th><th>پاس کا معیار</th><th>عام مسئلہ</th></tr></thead><tbody><tr><td>F01</td><td>کیا فائل کے نام کی شکل درست ہے</td><td>فائل کے نام کی شکل &quot;XX-دستاویز کا عنوان.md&quot; ہے، XX دو ہندسوں کا نمبر ہے</td><td>نمبر غائب، عنوان میں خالی جگہ، فائل کی توسیع غلط</td></tr><tr><td>F02</td><td>کیا دستاویز کے معلومات بلاک مکمل ہے</td><td>شروع میں نمبر، ماڈیول، بنیادی کلیدی الفاظ (3-5) کے ساتھ معلومات کی جدول شامل ہے</td><td>معلومات بلاک غائب یا فیلڈز نامکمل</td></tr><tr><td>F03</td><td>کیا دوسرے درجے کے عنوانوں کی تعداد معیار پر پوری ہے</td><td>مرکزی متن میں کم از کم 3 دوسرے درجے کے عنوانوں والے ابواب شامل ہیں</td><td>3 سے کم دوسرے درجے کے عنوان</td></tr><tr><td>F04</td><td>کیا ساختی عناصر استعمال کیے گئے ہیں</td><td>پڑھنے کی اہلیت کو بڑھانے کے لیے فہرستیں، جدولیں جیسے ساختی عناصر استعمال کریں</td><td>صرف خالص متن کے پیراگراف، کوئی فہرست یا جدول نہیں</td></tr><tr><td>F05</td><td>کیا اختتامیہ موجود ہے</td><td>آخر میں &quot;اختتامیہ&quot; کا پیراگراف ہے</td><td>اختتامیہ غائب</td></tr><tr><td>F06</td><td>کیا متعلقہ دستاویزات موجود ہیں</td><td>آخر میں 2-3 متعلقہ دستاویزات کے نمبر اور نام درج کریں</td><td>متعلقہ دستاویزات غائب یا متعلقہ دستاویزات موجود نہیں</td></tr><tr><td>F07</td><td>کیا الفاظ کی تعداد معیار پر پوری ہے</td><td>مرکزی متن 800 الفاظ سے کم نہیں ہے (عنوان اور میٹا معلومات کے علاوہ)</td><td>مرکزی متن 800 الفاظ سے کم</td></tr><tr><td>F08</td><td>کیا اصطلاحات کا استعمال یکساں ہے</td><td>&quot;ہینگ یوآن ژو&quot;، &quot;اینکر&quot;، &quot;سمبیوسس&quot; جیسے معیاری اصطلاحات استعمال کریں</td><td>اصطلاحات غیر مطابقت پذیر یا غیر معیاری اظہار کا استعمال</td></tr><tr><td>F09</td><td>کیا تحریری انداز مناسب ہے</td><td>سنگین، منظم ترتیب دستاویز کا انداز، کوئی بولی والا اظہار نہیں</td><td>بولی والا، من مانی اظہار کی ظاہری شکل</td></tr><tr><td>F10</td><td>کیا نمبر فہرست کے ساتھ مطابقت پذیر ہے</td><td>دستاویز کا نمبر اور عنوان SPEC.md میں 100 دستاویزات کی مکمل فہرست کے ساتھ مطابقت پذیر ہے</td><td>نمبر یا عنوان فہرست سے مطابقت نہیں رکھتا</td></tr></tbody></table><h2 id="_5-خود-جانچ-کا-عمل-اور-استعمال-کا-طریقہ" tabindex="-1">5. خود جانچ کا عمل اور استعمال کا طریقہ <a class="header-anchor" href="#_5-خود-جانچ-کا-عمل-اور-استعمال-کا-طریقہ" aria-label="Permalink to &quot;5. خود جانچ کا عمل اور استعمال کا طریقہ&quot;">​</a></h2><h3 id="_5-1-نئی-ترتیبات-کی-تخلیق-کے-لیے-خود-جانچ-کا-عمل" tabindex="-1">5.1 نئی ترتیبات کی تخلیق کے لیے خود جانچ کا عمل <a class="header-anchor" href="#_5-1-نئی-ترتیبات-کی-تخلیق-کے-لیے-خود-جانچ-کا-عمل" aria-label="Permalink to &quot;5.1 نئی ترتیبات کی تخلیق کے لیے خود جانچ کا عمل&quot;">​</a></h3><ol><li><strong>ابتدائی خود جانچ</strong>: تخلیق مکمل ہونے کے بعد، تخلیق کار اس خود جانچ کی جدول کے مطابق ہر آئٹم کی جانچ کرتا ہے، مسئلہ والے آئٹمز کو نشان زد کرتا ہے۔</li><li><strong>ترمیم اور تکمیل</strong>: نشان زدہ مسئلہ والے آئٹمز کی ترمیم کریں، یہ یقینی بنائیں کہ سب پاس ہو جائیں۔</li><li><strong>کراس آڈٹ</strong>: دوسرے ترتیب تخلیق کار کو کراس آڈٹ کے لیے جمع کرائیں، خاص طور پر ماڈیولز کے درمیان مطابقت کی جانچ پر توجہ دیں۔</li><li><strong>کمیٹی کی منظوری</strong>: اہم ترتیب کی تبدیلیوں کو ترتیب کی دیکھ بھال کی کمیٹی کے سامنے منظوری کے لیے جمع کرانا ضروری ہے۔</li><li><strong>آرکائیو اور تازہ کاری</strong>: تمام جانچ پاس کرنے کے بعد، رسمی طور پر ترتیب کے نظام میں شامل کیا جاتا ہے اور متعلقہ انڈیکس دستاویزات کو تازہ کیا جاتا ہے۔</li></ol><h3 id="_5-2-پرانی-ترتیبات-کی-ترمیم-کے-لیے-خود-جانچ-کا-عمل" tabindex="-1">5.2 پرانی ترتیبات کی ترمیم کے لیے خود جانچ کا عمل <a class="header-anchor" href="#_5-2-پرانی-ترتیبات-کی-ترمیم-کے-لیے-خود-جانچ-کا-عمل" aria-label="Permalink to &quot;5.2 پرانی ترتیبات کی ترمیم کے لیے خود جانچ کا عمل&quot;">​</a></h3><ol><li><strong>اثرات کی تشخیص</strong>: ترمیم شدہ مواد سے ممکنہ طور پر متاثر ہونے والے دوسرے دستاویزات اور ترتیب ماڈیولز کی تشخیص کریں۔</li><li><strong>متعلقہ جانچ</strong>: تمام متاثرہ متعلقہ دستاویزات کی مطابقت کی جانچ کریں۔</li><li><strong>ہم وقت ترمیم</strong>: متعلقہ دستاویزات میں متاثرہ مواد کی ہم وقت ترمیم کریں۔</li><li><strong>ورژن کا ریکارڈ</strong>: دستاویز 99 &quot;دستاویز کا ورژن اور دیکھ بھال کی ہدایات&quot; میں ترمیم شدہ مواد اور ورژن نمبر ریکارڈ کریں۔</li><li><strong>اعلان اور اطلاع</strong>: اہم ترمیموں کو تمام ترتیب استعمال کرنے والوں کے سامنے تبدیلی کا اعلان شائع کرنا ضروری ہے۔</li></ol><h3 id="_5-3-باقاعدہ-مکمل-خود-جانچ" tabindex="-1">5.3 باقاعدہ مکمل خود جانچ <a class="header-anchor" href="#_5-3-باقاعدہ-مکمل-خود-جانچ" aria-label="Permalink to &quot;5.3 باقاعدہ مکمل خود جانچ&quot;">​</a></h3><p>ترتیب کی دیکھ بھال کی کمیٹی ہر سہ ماہی میں ایک بار مکمل ترتیب مطابقت کی خود جانچ کرتی ہے، تمام 100 دستاویزات کی منظم جانچ کرتی ہے، ممکنہ ترتیب کے تضاد اور منطقی عدم مطابقت کو دریافت کرتی ہے۔ خود جانچ کے نتائج &quot;سہ ماہی ترتیب مطابقت کی رپورٹ&quot; کی شکل میں شائع کیے جاتے ہیں، تمام ترتیب استعمال کرنے والوں کے لیے کھلے رہتے ہیں۔</p><h2 id="اختتامیہ" tabindex="-1">اختتامیہ <a class="header-anchor" href="#اختتامیہ" aria-label="Permalink to &quot;اختتامیہ&quot;">​</a></h2><p>ترتیبات کے تضاد کی خود جانچ کی جدول اینکر سمبیوسس تہذیب کے ترتیب کے نظام کا &quot;معیار کا آئین&quot; ہے۔ یہ منظم، فہرست والے جانچ کے آئٹمز کے ذریعے، اس بات کی ضمانت دیتا ہے کہ ترتیب کا نظام مسلسل توسیع اور ترمیم کے عمل میں ہمیشہ منطقی خود مطابقت اور اصطلاحات کی یکسانیت برقرار رکھے۔ ایک بڑے ترتیب کے نظام کا سب سے بڑا خوف مواد کی کم سنترپتی نہیں ہے، بلکہ اندرونی تضادوں کا بڑھنا اور پہلے اور بعد میں عدم مطابقت ہے۔ اس خود جانچ کی جدول کا وجود، اس لیے ہے کہ اینکر سمبیوسس تہذیب کے ترتیب کا نظام کھلے پن اور ترقی کی صلاحیت کو برقرار رکھتے ہوئے، ہمیشہ ایک مضبوط مطابقت کی بنیاد رکھے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>99-دستاویز کا ورژن اور دیکھ بھال کی ہدایات</li><li>90-اصطلاحات کا لغت</li><li>00-ہینگ یوآن ژو کائنات کا جائزہ</li></ul>',33)])])}const _=d(e,[["render",h]]);export{s as __pageData,_ as default};
